    '/* DB2 schema sample — declared constraints only. */',
    'CREATE SCHEMA sales;',
    '',
    'CREATE TABLE sales.department (',
    '  dept_id      INTEGER       NOT NULL GENERATED ALWAYS AS IDENTITY (START WITH 10 INCREMENT BY 10),',
    '  dept_name    VARCHAR(80)   NOT NULL,',
    '  location     VARCHAR(80),',
