    '  customer_name VARCHAR(120) NOT NULL,',
    '  email        VARCHAR(200)  NOT NULL,',
    '  country      CHAR(2),',
    '  CONSTRAINT pk_customer PRIMARY KEY (customer_id)',
    ');',
    '',
    'CREATE TABLE sales.orders (',
