    '  product_id   INTEGER       NOT NULL GENERATED ALWAYS AS IDENTITY,',
    '  sku          VARCHAR(40)   NOT NULL,',
    '  product_name VARCHAR(160)  NOT NULL,',
    '  unit_price   DECIMAL(9,2)  NOT NULL,',
